public:
    void wordFrequency() {
        std::ifstream in("words.txt");
        std::map<std::string,int> cnt;
        std::string w;
        while (in >> w) cnt[w]++;
        std::vector<std::pair<int,std::string>> v;
        for (auto& p : cnt) v.push_back({p.second, p.first});
