import java.util.*;
import java.nio.file.*;
class Solution {
    public void wordFrequency() throws Exception {
        Map<String,Integer> cnt = new HashMap<>();
        for (String w : new String(Files.readAllBytes(Paths.get("words.txt"))).split("\\s+"))
            if (!w.isEmpty()) cnt.merge(w, 1, Integer::sum);
        cnt.entrySet().stream()
           .sorted((a,b)->b.getValue()-a.getValue())
           .forEach(e->System.out.println(e.getKey()+" "+e.getValue()));
    }
}

